-- Human-verified shipper and facility directory. No hours, availability, directions, or outreach is inferred.
begin;
create table public.facility_profiles(id uuid primary key default gen_random_uuid(),company_id uuid not null,facility_name text not null check(char_length(facility_name)between 2 and 200),facility_type text not null check(facility_type in('shipper','receiver','cold_storage','produce_house','warehouse','cross_dock','other')),address_line text not null check(char_length(address_line)between 3 and 300),city text not null check(char_length(city)between 2 and 100),state text not null check(state~'^[A-Z]{2}$'),postal_code text,contact_name text,phone text,email text,appointment_note text,check_in_note text,parking_note text,lumper_note text,temperature_note text,status text not null default'active'check(status in('active','inactive')),factual_note text not null check(char_length(factual_note)between 3 and 2000),verified_by uuid not null,request_id text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,id),unique(company_id,request_id));
create table public.facility_profile_events(id uuid primary key default gen_random_uuid(),company_id uuid not null,facility_id uuid not null,event_type text not null check(event_type in('created','updated','status_changed')),before_state jsonb,after_state jsonb,factual_note text not null,actor_user_id uuid not null,request_id text not null,created_at timestamptz not null default now(),unique(company_id,request_id),constraint facility_event_company_fk foreign key(company_id,facility_id)references public.facility_profiles(company_id,id));
create index facility_company_location_idx on public.facility_profiles(company_id,state,city,facility_type,status);
alter table public.facility_profiles enable row level security;alter table public.facility_profile_events enable row level security;create policy facility_authorized_select on public.facility_profiles for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting','maintenance'));create policy facility_events_authorized_select on public.facility_profile_events for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting','maintenance'));
revoke all privileges on table public.facility_profiles,public.facility_profile_events from public,anon,authenticated,service_role;grant select on table public.facility_profiles,public.facility_profile_events to authenticated,service_role;grant insert,update on table public.facility_profiles to service_role;grant insert on table public.facility_profile_events to service_role;
create or replace function public.list_verified_facilities()returns table(id uuid,facility_name text,facility_type text,address_line text,city text,state text,postal_code text,contact_name text,phone text,email text,appointment_note text,check_in_note text,parking_note text,lumper_note text,temperature_note text,status text,factual_note text,updated_at timestamptz)language sql stable security definer set search_path=public as $$select f.id,f.facility_name,f.facility_type,f.address_line,f.city,f.state,f.postal_code,f.contact_name,f.phone,f.email,f.appointment_note,f.check_in_note,f.parking_note,f.lumper_note,f.temperature_note,f.status,f.factual_note,f.updated_at from public.facility_profiles f where f.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting','maintenance')order by case when f.status='active'then 0 else 1 end,f.state,f.city,f.facility_name$$;
create or replace function public.save_verified_facility(p_facility_id uuid,p_facility_name text,p_facility_type text,p_address_line text,p_city text,p_state text,p_postal_code text,p_contact_name text,p_phone text,p_email text,p_appointment_note text,p_check_in_note text,p_parking_note text,p_lumper_note text,p_temperature_note text,p_status text,p_note text,p_request_id text)returns uuid language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;b jsonb;a jsonb;e text;begin if c is null or u is null or r not in('super_admin','owner','dispatcher','safety')then raise exception'Not authorized';end if;if p_request_id is null or char_length(p_request_id)not between 8 and 200 or char_length(trim(p_facility_name))not between 2 and 200 or p_facility_type not in('shipper','receiver','cold_storage','produce_house','warehouse','cross_dock','other')or char_length(trim(p_address_line))not between 3 and 300 or char_length(trim(p_city))not between 2 and 100 or upper(trim(p_state))!~'^[A-Z]{2}$'or p_status not in('active','inactive')or char_length(trim(p_note))not between 3 and 2000 or(p_email is not null and trim(p_email)<>''and p_email!~*'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')then raise exception'Invalid facility facts';end if;select facility_id into x from public.facility_profile_events where company_id=c and request_id=p_request_id;if x is not null then return x;end if;if p_facility_id is null then insert into public.facility_profiles(company_id,facility_name,facility_type,address_line,city,state,postal_code,contact_name,phone,email,appointment_note,check_in_note,parking_note,lumper_note,temperature_note,status,factual_note,verified_by,request_id)values(c,trim(p_facility_name),p_facility_type,trim(p_address_line),trim(p_city),upper(trim(p_state)),nullif(trim(p_postal_code),''),nullif(trim(p_contact_name),''),nullif(trim(p_phone),''),nullif(lower(trim(p_email)),''),nullif(trim(p_appointment_note),''),nullif(trim(p_check_in_note),''),nullif(trim(p_parking_note),''),nullif(trim(p_lumper_note),''),nullif(trim(p_temperature_note),''),p_status,trim(p_note),u,p_request_id)returning id into x;e:='created';else select to_jsonb(v)into b from public.facility_profiles v where v.company_id=c and v.id=p_facility_id for update;if b is null then raise exception'Facility not found';end if;update public.facility_profiles set facility_name=trim(p_facility_name),facility_type=p_facility_type,address_line=trim(p_address_line),city=trim(p_city),state=upper(trim(p_state)),postal_code=nullif(trim(p_postal_code),''),contact_name=nullif(trim(p_contact_name),''),phone=nullif(trim(p_phone),''),email=nullif(lower(trim(p_email)),''),appointment_note=nullif(trim(p_appointment_note),''),check_in_note=nullif(trim(p_check_in_note),''),parking_note=nullif(trim(p_parking_note),''),lumper_note=nullif(trim(p_lumper_note),''),temperature_note=nullif(trim(p_temperature_note),''),status=p_status,factual_note=trim(p_note),verified_by=u,request_id=p_request_id,updated_at=now()where company_id=c and id=p_facility_id returning id into x;e:=case when b->>'status'<>p_status then'status_changed'else'updated'end;end if;select to_jsonb(v)into a from public.facility_profiles v where v.company_id=c and v.id=x;insert into public.facility_profile_events(company_id,facility_id,event_type,before_state,after_state,factual_note,actor_user_id,request_id)values(c,x,e,b,a,trim(p_note),u,p_request_id);return x;end$$;
revoke all on function public.list_verified_facilities(),public.save_verified_facility(uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text)from public,anon;grant execute on function public.list_verified_facilities(),public.save_verified_facility(uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text)to authenticated;commit;
